// Seed *data* for the catalogue. After first boot these live in the database and are
// edited through the admin console; this file is never read at request time.
type Q = { key: string; label: string; type: 'number' | 'select' | 'boolean'; options?: string[]; min?: number; max?: number; default?: any; help?: string; manual_when?: string };
type R = { rule_type: string; question_key?: string; label: string; hours?: number; params?: any; is_custom?: boolean };
export interface SvcDef {
  key: string; product: 'surveysparrow' | 'thrivesparrow'; category: string; module?: string; name: string; desc: string;
  icon: string; phase?: number; alloc: keyof typeof ALLOC; deliverables: string[]; q: Q[]; r: R[];
  complexityQ?: string; manual?: string; dependsOn?: string[];
}

export const ALLOC = {
  build: { consultant: 70, architect: 10, qa: 10, pm: 10 },
  data: { analyst: 60, consultant: 20, qa: 10, pm: 10 },
  integration: { integration: 55, architect: 15, consultant: 10, qa: 10, pm: 10 },
  analytics: { analyst: 65, consultant: 15, qa: 10, pm: 10 },
  config: { consultant: 55, architect: 20, qa: 10, pm: 15 },
  training: { trainer: 80, consultant: 10, pm: 10 },
  uat: { qa: 60, consultant: 25, pm: 15 },
  deploy: { consultant: 60, qa: 15, pm: 25 },
};

const N = (key: string, label: string, def: number, min = 0, max = 100000, help?: string): Q => ({ key, label, type: 'number', default: def, min, max, help });
const S = (key: string, label: string, options: string[], def?: string, manual_when?: string, help?: string): Q => ({ key, label, type: 'select', options, default: def ?? options[0], manual_when, help });
const B = (key: string, label: string, def = false, manual_when?: string, help?: string): Q => ({ key, label, type: 'boolean', default: def, manual_when, help });
const CX = S('complexity', 'Complexity', ['Basic', 'Medium', 'Advanced'], 'Medium');

const base = (hours: number, label = 'Discovery, setup & project coordination'): R => ({ rule_type: 'base', label, hours });
const min = (hours: number): R => ({ rule_type: 'minimum', label: 'Minimum effort', hours });
const unit = (key: string, hours: number, label: string, free = 0): R => ({ rule_type: 'per_unit', question_key: key, label, hours, params: { free } });
const prod = (keys: string[], hours: number, label: string, subtract: Record<string, number> = {}): R => ({ rule_type: 'product', label, hours, params: { keys, subtract } });
const band = (key: string, bands: [number | null, number][], label: string): R => ({ rule_type: 'band', question_key: key, label, params: { bands: bands.map(([upTo, hours]) => ({ upTo, hours })) } });
const opt = (key: string, map: Record<string, number>, label: string): R => ({ rule_type: 'option', question_key: key, label, params: { map } });
const flag = (key: string, hours: number, label: string, is_custom = false): R => ({ rule_type: 'flag', question_key: key, label, hours, is_custom });

const EMP_BAND: [number | null, number][] = [[250, 3], [1000, 6], [5000, 12], [20000, 20], [null, 32]];
const INTEG_Q = (platforms: string[], extra: Q[] = []): Q[] => [
  S('platform', 'Integration platform', platforms, undefined, 'Other'),
  N('objects', 'Number of objects / modules involved', 2, 1, 50),
  N('fields', 'Number of fields to be mapped', 20, 1, 1000),
  S('direction', 'Direction of synchronisation', ['One-way (into SurveySparrow)', 'One-way (out of SurveySparrow)', 'Bi-directional']),
  N('triggers', 'Number of triggers', 2, 0, 100),
  B('custom_api', 'Custom API development required?'),
  B('client_eng', 'Client-side engineering assistance required?'),
  ...extra,
];
const INTEG_R = (): R[] => [
  base(8, 'Integration discovery, authentication & sandbox setup'),
  unit('objects', 3, 'Object / module configuration'),
  unit('fields', 0.35, 'Field mapping & validation'),
  opt('direction', { 'One-way (into SurveySparrow)': 0, 'One-way (out of SurveySparrow)': 0, 'Bi-directional': 8 }, 'Bi-directional sync logic & conflict handling'),
  unit('triggers', 2, 'Trigger configuration & testing'),
  flag('custom_api', 16, 'Custom API development', true),
  flag('client_eng', 8, 'Client-side engineering coordination', true),
  min(12),
];
const INTEG_D = ['Configured and tested integration', 'Field & object mapping document', 'Integration test evidence'];

